-- ----------------------------
-- Table structure for message
-- ----------------------------
DROP TABLE IF EXISTS `message`;
CREATE TABLE `message` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `send_user_id` varchar(40) DEFAULT NULL,
  `receive_user_id` varchar(40) DEFAULT NULL,
  `receive_user_email` varchar(80) DEFAULT NULL,
  `seat_id` varchar(50) DEFAULT NULL,
  `send_status` int(11) DEFAULT NULL,
  `receive_suggestion` varchar(255) DEFAULT NULL,
  `send_msg` varchar(255) DEFAULT NULL,
  `is_read` int(11) DEFAULT NULL,
  `is_pass` int(11) DEFAULT NULL,
  `send_time` datetime DEFAULT NULL,
  `read_time` datetime DEFAULT NULL,
  `end_time` datetime DEFAULT NULL,
  `type` varchar(30) DEFAULT NULL,
  `count` varchar(50) DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL,
  `deleted` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `se` (`send_user_id`) USING BTREE,
  CONSTRAINT `se` FOREIGN KEY (`send_user_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8 ROW_FORMAT=COMPACT;

