-- ----------------------------
-- Table structure for users
-- ----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) DEFAULT NULL,
  `domain_accounts` varchar(255) DEFAULT NULL,
  `age` int(11) DEFAULT NULL,
  `join_time` date DEFAULT NULL,
  `leave_time` date DEFAULT NULL,
  `seat_id` varchar(50) DEFAULT NULL,
  `department_id` int(11) DEFAULT NULL,
  `user_id` varchar(30) DEFAULT NULL,
  `email` varchar(80) DEFAULT NULL,
  `mobile` varchar(80) DEFAULT NULL,
  `sex` varchar(12) DEFAULT NULL,
  `status` int(11) DEFAULT NULL,
  `password` varchar(255) DEFAULT NULL,
  `role` int(11) DEFAULT NULL,
  `deleted` int(11) DEFAULT '0',
  `group_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `depart` (`department_id`) USING BTREE,
  KEY `delet` (`deleted`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `ro` (`role`) USING BTREE,
  KEY `group` (`group_id`) USING BTREE,
  CONSTRAINT `depart` FOREIGN KEY (`department_id`) REFERENCES `department` (`id`),
  CONSTRAINT `group` FOREIGN KEY (`group_id`) REFERENCES `group` (`id`),
  CONSTRAINT `ro` FOREIGN KEY (`role`) REFERENCES `role` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=944 DEFAULT CHARSET=utf8 ROW_FORMAT=COMPACT;

